import { build } from 'esbuild';
import { writeFile } from 'node:fs/promises';
const result = await build({
  entryPoints: ['src/lib/season-runtime.ts'],
  bundle: true,
  minify: true,
  format: 'iife',
  target: ['es2018'],
  legalComments: 'eof',
  write: false,
});
const runtime = result.outputFiles[0].text.replace(/[ \t]+$/gm, '');
await writeFile('public/desktop/season-runtime.js', runtime);
await writeFile(
  'src/lib/season-boot.ts',
  '// Generated by scripts/build-season-runtime.mjs. Do not edit.\nexport const SEASON_BOOT = ' +
    JSON.stringify(runtime) +
    ';\n',
);
